1	#!/usr/bin/env bash
2	# GRPO | Qwen3-4B | FSDP training | NVIDIA GPUs or Ascend NPUs
3	#
4	# INFER_BACKEND controls rollout backend: vllm
5	
6	set -xeuo pipefail
7	
8	# ---- user-adjustable ----
9	# DEVICE is auto-detected by probing torch_npu; override only for special cases.
10	DEVICE=${DEVICE:-$(python3 -c 'import torch_npu' 2>/dev/null && echo npu || echo gpu)}
11	INFER_BACKEND=${INFER_BACKEND:-vllm}
12	MODEL_PATH=${MODEL_PATH:-Qwen/Qwen3-4B}
13	TRAIN_FILE=${TRAIN_FILE:-$HOME/data/gsm8k/train.parquet}
14	TEST_FILE=${TEST_FILE:-$HOME/data/gsm8k/test.parquet}
15	NNODES=${NNODES:-1}
16	NGPUS_PER_NODE=${NGPUS_PER_NODE:-8}
17	
18	TRAIN_BATCH_SIZE=${TRAIN_BATCH_SIZE:-512}
19	PPO_MINI_BATCH_SIZE=${PPO_MINI_BATCH_SIZE:-256}
20	PPO_MICRO_BATCH_SIZE_PER_GPU=${PPO_MICRO_BATCH_SIZE_PER_GPU:-2}
21	LOG_PROB_MICRO_BATCH_SIZE_PER_GPU=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU:-2}
22	MAX_PROMPT_LENGTH=${MAX_PROMPT_LENGTH:-1024}
23	MAX_RESPONSE_LENGTH=${MAX_RESPONSE_LENGTH:-1024}
24	
25	ACTOR_LR=${ACTOR_LR:-1e-6}
26	KL_LOSS_COEF=${KL_LOSS_COEF:-0.001}
27	ENTROPY_COEFF=${ENTROPY_COEFF:-0}
28	
29	ROLLOUT_TP=${ROLLOUT_TP:-2}
30	ROLLOUT_GPU_MEM_UTIL=${ROLLOUT_GPU_MEM_UTIL:-0.6}
31	ROLLOUT_N=${ROLLOUT_N:-5}
32	
33	PROJECT_NAME=${PROJECT_NAME:-verl_grpo_example_geo3k}
34	EXPERIMENT_NAME=${EXPERIMENT_NAME:-glm41v_9b_function_rm}
35	SAVE_FREQ=${SAVE_FREQ:-20}
36	TEST_FREQ=${TEST_FREQ:-5}
37	TOTAL_EPOCHS=${TOTAL_EPOCHS:-15}
38	
39	# ---- end user-adjustable ----
40	
41	case "${DEVICE}" in
42	    gpu)
43	        ;;
44	    npu)
45	        export VLLM_USE_V1=1
46	        export TASK_QUEUE_ENABLE=2
47	        export CPU_AFFINITY_CONF=1
48	        export LD_PRELOAD="/usr/lib/aarch64-linux-gnu/libjemalloc.so.2${LD_PRELOAD:+:$LD_PRELOAD}"
49	        NGPUS_PER_NODE=16
50	        ROLLOUT_GPU_MEM_UTIL=0.9
51	        ;;
52	    *)
53	        echo "Unsupported DEVICE=${DEVICE}. Expected 'gpu' or 'npu'." >&2
54	        exit 1
55	        ;;
56	esac
57	
58	########################### parameter arrays ###########################
59	
60	DATA=(
61	    algorithm.adv_estimator=grpo
62	    data.train_files=${TRAIN_FILE}
63	    data.val_files=${TEST_FILE}
64	    data.train_batch_size=${TRAIN_BATCH_SIZE}
65	    data.max_prompt_length=${MAX_PROMPT_LENGTH}
66	    data.max_response_length=${MAX_RESPONSE_LENGTH}
67	    data.filter_overlong_prompts=True
68	    data.truncation='error'
69	    algorithm.use_kl_in_reward=False
70	)
71	
72	MODEL=(
73	    actor_rollout_ref.model.path=${MODEL_PATH}
74	    actor_rollout_ref.model.use_remove_padding=True
75	    actor_rollout_ref.model.enable_gradient_checkpointing=True
76	)
77	
78	ACTOR=(
79	    actor_rollout_ref.actor.optim.lr=${ACTOR_LR}
80	    actor_rollout_ref.actor.ppo_mini_batch_size=${PPO_MINI_BATCH_SIZE}
81	    actor_rollout_ref.actor.ppo_micro_batch_size_per_gpu=${PPO_MICRO_BATCH_SIZE_PER_GPU}
82	    actor_rollout_ref.actor.use_kl_loss=True
83	    actor_rollout_ref.actor.kl_loss_coef=${KL_LOSS_COEF}
84	    actor_rollout_ref.actor.kl_loss_type=low_var_kl
85	    actor_rollout_ref.actor.entropy_coeff=${ENTROPY_COEFF}
86	    actor_rollout_ref.actor.fsdp_config.param_offload=False
87	    actor_rollout_ref.actor.fsdp_config.optimizer_offload=False
88	    actor_rollout_ref.actor.ppo_max_token_len_per_gpu=3000
89	    actor_rollout_ref.actor.use_dynamic_bsz=True
90	)
91	
92	ROLLOUT=(
93	    actor_rollout_ref.rollout.log_prob_micro_batch_size_per_gpu=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU}
94	    actor_rollout_ref.rollout.tensor_model_parallel_size=${ROLLOUT_TP}
95	    actor_rollout_ref.rollout.name=${INFER_BACKEND}
96	    actor_rollout_ref.rollout.gpu_memory_utilization=${ROLLOUT_GPU_MEM_UTIL}
97	    actor_rollout_ref.rollout.enable_chunked_prefill=False
98	    actor_rollout_ref.rollout.enforce_eager=False
99	    actor_rollout_ref.rollout.free_cache_engine=True
100	    actor_rollout_ref.rollout.log_prob_use_dynamic_bsz=True
101	    actor_rollout_ref.rollout.log_prob_max_token_len_per_gpu=4096
102	    actor_rollout_ref.rollout.checkpoint_engine.update_weights_bucket_megabytes=4096
103	    actor_rollout_ref.rollout.n=${ROLLOUT_N}
104	)
105	
106	REF=(
107	    actor_rollout_ref.ref.log_prob_micro_batch_size_per_gpu=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU}
108	    actor_rollout_ref.ref.fsdp_config.param_offload=True
109	    actor_rollout_ref.ref.log_prob_use_dynamic_bsz=True
110	    actor_rollout_ref.ref.log_prob_max_token_len_per_gpu=8192
111	)
112	
113	TRAINER=(
114	    trainer.critic_warmup=0
115	    trainer.logger='["console","wandb"]'
116	    trainer.project_name=${PROJECT_NAME}
117	    trainer.experiment_name=${EXPERIMENT_NAME}
118	    trainer.n_gpus_per_node=${NGPUS_PER_NODE}
119	    trainer.nnodes=${NNODES}
120	    trainer.save_freq=${SAVE_FREQ}
121	    trainer.test_freq=${TEST_FREQ}
122	    trainer.total_epochs=${TOTAL_EPOCHS}
123	)
124	
125	EXTRA=(
126	)
127	
128	########################### launch ###########################
129	python3 -m verl.trainer.main_ppo \
130	    "${DATA[@]}" \
131	    "${MODEL[@]}" \
132	    "${ACTOR[@]}" \
133	    "${ROLLOUT[@]}" \
134	    "${REF[@]}" \
135	    "${TRAINER[@]}" \
136	    "${EXTRA[@]}" \
137	    "$@"
