import json, re
for fn in ["0.jsonl", "50.jsonl", "100.jsonl"]:
    with open(f"/workspace/results/run100/val_generations/{fn}") as f:
        lines = [json.loads(l) for l in f]
    boxed_corr = 0
    boxed_total = 0
    any_last_num_corr = 0
    hash_num_corr = 0
    for l in lines:
        gts = float(l["gts"])
        nums = re.findall(r"\-?[0-9]+(?:\.[0-9]+)?", l["output"].replace(",", ""))
        if nums and float(nums[-1]) == gts:
            any_last_num_corr += 1
        b = re.findall(r"\\boxed\{([^}]+)\}", l["output"])
        if b:
            boxed_total += 1
            bnums = re.findall(r"\-?[0-9]+(?:\.[0-9]+)?", b[-1].replace(",", ""))
            if bnums and float(bnums[-1]) == gts:
                boxed_corr += 1
        h = re.findall(r"####\s*\$?(\-?[0-9\.\,]+)", l["output"])
        if h:
            try:
                if float(h[-1].replace(",", "").rstrip(".")) == gts:
                    hash_num_corr += 1
            except:
                pass
    s_acc = sum(l["score"] for l in lines)/len(lines)
    print(f"{fn}: strict={s_acc:.4f}, hash_num_corr={hash_num_corr/len(lines):.4f}, last_num_corr={any_last_num_corr/len(lines):.4f}, boxed={boxed_corr}/{boxed_total}")
'

